    38  static char *get_argument(char **cmd, char **arglist)
    39  {
    40          GString *str;
    41          char *ret;
    42          int max, arg, argcount;
    43
    44          arg = 0;
    45          max = -1;
    46
    47          argcount = arglist == NULL ? 0 : g_strv_length(arglist);
    48
    49          if (**cmd == '*') {
    50                  /* get all arguments */
    51          } else if (**cmd == '~') {
    52                  /* get last argument */
    53                  arg = max = argcount-1;
    54          } else {
    55                  if (i_isdigit(**cmd)) {
    56                          /* first argument */
    57                          arg = max = (**cmd)-'0';
    58                          (*cmd)++;
    59                  }
    60
    61                  if (**cmd == '-') {
    62                          /* get more than one argument */
    63                          (*cmd)++;
    64                          if (!i_isdigit(**cmd))
    65                                  max = -1; /* get all the rest */
    66                          else {
    67                                  max = (**cmd)-'0';
    68                                  (*cmd)++;
    69                          }
    70                  }
    71                  (*cmd)--;
    72          }
    73
    74          str = g_string_new(NULL);
    75          while (arg >= 0 && arg < argcount && (arg <= max || max == -1)) {
    76                  g_string_append(str, arglist[arg]);
    77                  g_string_append_c(str, ' ');
    78                  arg++;
    79          }
    80          if (str->len > 0) g_string_truncate(str, str->len-1);
    81
    82          ret = str->str;
    83          g_string_free(str, FALSE);
    84          return ret;
    85  }
