   118  static char *get_long_variable(char **cmd, SERVER_REC *server,
   119                                 void *item, int *free_ret, int getname)
   120  {
   121          char *start, *var, *ret;
   122
   123          /* get variable name */
   124          start = *cmd;
   125          while (isvarchar((*cmd)[1])) (*cmd)++;
   126
   127          var = g_strndup(start, (int) (*cmd-start)+1);
   128          if (getname) {
   129                  *free_ret = TRUE;
   130                  return var;
   131          }
   132          ret = get_long_variable_value(var, server, item, free_ret);
   133          g_free(var);
   134          return ret;
   135  }
