   137  /* return the value of the variable found from `cmd'.
   138     if 'getname' is TRUE, return the name of the variable instead it's value */
   139  static char *get_variable(char **cmd, SERVER_REC *server, void *item,
   140                            char **arglist, int *free_ret, int *arg_used,
   141                            int getname)
   142  {
   143          EXPANDO_FUNC func;
   144
   145          if (isarg(**cmd)) {
   146                  /* argument */
   147                  *free_ret = TRUE;
   148                  if (arg_used != NULL) *arg_used = TRUE;
   149                  return getname ? g_strdup_printf("%c", **cmd) :
   150                          get_argument(cmd, arglist);
   151          }
   152
   153          if (i_isalpha(**cmd) && isvarchar((*cmd)[1])) {
   154                  /* long variable name.. */
   155                  return get_long_variable(cmd, server, item, free_ret, getname);
   156          }
   157
   158          /* single character variable. */
   159          if (getname) {
   160                  *free_ret = TRUE;
   161                  return g_strdup_printf("%c", **cmd);
   162          }
   163          *free_ret = FALSE;
   164          func = expando_find_char(**cmd);
   165          if (func == NULL)
   166                  return NULL;
   167          else {
   168                  char str[2];
   169
   170                  str[0] = **cmd; str[1] = '\0';
   171                  current_expando = str;
   172                  return func(server, item, free_ret);
   173          }
   174  }
