   176  static char *get_history(char **cmd, void *item, int *free_ret)
   177  {
   178          char *start, *text, *ret;
   179
   180          /* get variable name */
   181          start = ++(*cmd);
   182          while (**cmd != '\0' && **cmd != '!') (*cmd)++;
   183
   184          if (history_func == NULL)
   185                  ret = NULL;
   186          else {
   187                  text = g_strndup(start, (int) (*cmd-start));
   188                  ret = history_func(text, item, free_ret);
   189                  g_free(text);
   190          }
   191
   192          if (**cmd == '\0') (*cmd)--;
   193          return ret;
   194  }
